import { subscript } from '@genshin-optimizer/pando/engine'
import type { WengineKey } from '@genshin-optimizer/zzz/consts'
import { mappedStats } from '@genshin-optimizer/zzz/stats'
import {
  allBoolConditionals,
  own,
  ownBuff,
  percent,
  registerBuff,
} from '../../util'
import {
  cmpSpecialtyAndEquipped,
  entriesForWengine,
  registerWengine,
  showSpecialtyAndEquipped,
} from '../util'

const key: WengineKey = 'CrimsonThirst'
const dm = mappedStats.wengine[key]
const { phase } = own.wengine

const { exSpecialMaim } = allBoolConditionals(key)

const sheet = registerWengine(
  key,
  // Handles base stats and passive buffs
  entriesForWengine(key),

  // Passive buffs
  registerBuff(
    'passive_crit_',
    ownBuff.combat.crit_.add(
      cmpSpecialtyAndEquipped(key, percent(subscript(phase, dm.crit_)))
    ),
    showSpecialtyAndEquipped(key)
  ),
  registerBuff(
    'passive_electric_dmg_',
    ownBuff.combat.dmg_.electric.add(
      cmpSpecialtyAndEquipped(key, percent(subscript(phase, dm.electric_dmg_)))
    ),
    showSpecialtyAndEquipped(key)
  ),

  // Conditional buffs
  registerBuff(
    'cond_electric_sharp_dmg_',
    ownBuff.combat.sharp_dmg_.electric.add(
      cmpSpecialtyAndEquipped(
        key,
        exSpecialMaim.ifOn(percent(subscript(phase, dm.electric_sharp_dmg_)))
      )
    ),
    showSpecialtyAndEquipped(key)
  )
)
export default sheet
